```json
{
  "title": "Personal remittances as a share of GDP, 1986",
  "x_axis": "%",
  "y_axis": "Country",
  "units": "",
  "ticks": [0%, 1%, 2%, 3%, 4%, 5%, 6%, 7%],
  "legend": {
    "Morocco": "#7f68e9",
    "Portugal": "#d95f02",
    "Saint Lucia": "#1b9e77"
  },
  "data_points": [
    {"country": "Morocco", "value": "7.19"},
    {"country": "Portugal", "value": "6.85"},
    {"country": "Saint Lucia", "value": "6.2"}
  ],
  "notes": "Personal remittances comprise personal transfers and compensation of employees. Personal transfers consist of all current transfers in cash or in kind made or received by resident households to or from nonresident households. Compensation of employees refers to the income of border, seasonal, and other short-term workers who are employed in an economy where they are not resident and of residents employed by nonresident entities."
}
```

